typedef struct {
    int W; // Destination Register (Write)
    int R1, R2; // Source Registers (Read)
} Instruction;

// I_Prev executes before I_Next
bool check_dependencies(Instruction I_Prev, Instruction I_Next) {
    // 1. RAW (Read After Write - True Dependency: I_Prev writes, I_Next reads)
    if (I_Prev.W == I_Next.R1 || I_Prev.W == I_Next.R2) return true; // Hazard

    // 2. WAW (Write After Write - Output Dependency: Both write same register)
    if (I_Prev.W == I_Next.W && I_Prev.W != 0) return true;

    // 3. WAR (Write After Read - Anti Dependency: I_Prev reads, I_Next writes)
    if (I_Prev.R1 == I_Next.W || I_Prev.R2 == I_Next.W) return true;

    return false;
}
